steps.script:
# Same position as exam mv09_arm_the_indirect_battery (without the profile
# line): Custodian Guard Beta with a constructed BS 3+ [BLAST, INDIRECT FIRE]
# mortar and Delta with a BS 5+ [INDIRECT FIRE] lobba on the west edge, our
# Prosecutors on obj_center, the enemy Custodian Guard Alpha Hidden in
# area-medium-35, everyone else parked.
var st = GameState.state
var mortar = {"name": "Exam mortar", "type": "Ranged", "range": "36", "attacks": "2", "ballistic_skill": "3", "strength": "8", "ap": "-2", "damage": "2", "special_rules": "blast, indirect fire", "abilities": [{"id": "blast"}, {"id": "indirect_fire"}], "granted_by": "exam"}
var lobba = {"name": "Exam lobba", "type": "Ranged", "range": "48", "attacks": "3", "ballistic_skill": "5", "strength": "5", "ap": "0", "damage": "1", "special_rules": "blast, indirect fire", "abilities": [{"id": "blast"}, {"id": "indirect_fire"}], "granted_by": "exam"}
var arm = {"U_CUSTODIAN_GUARD_B": mortar, "U_CUSTODIAN_GUARD_D": lobba}
for uid in arm:
	var u = st.units[uid]
	var kept = []
	for w in u.meta.weapons:
		if str(w.get("type", "")).to_lower() != "ranged":
			kept.append(w)
	kept.append(arm[uid])
	u.meta.weapons = kept
var place = {
	"U_CUSTODIAN_GUARD_B": [Vector2(60, 870), Vector2(125, 870), Vector2(190, 870), Vector2(92, 935), Vector2(157, 935)],
	"U_CUSTODIAN_GUARD_D": [Vector2(60, 720), Vector2(125, 720), Vector2(190, 720), Vector2(92, 785), Vector2(157, 785)],
	"U_PROSECUTORS_A": [Vector2(790, 1340), Vector2(845, 1340), Vector2(790, 1395), Vector2(845, 1395)],
	"U_CUSTODIAN_GUARD_A_P2": [Vector2(1255, 1385), Vector2(1255, 1450), Vector2(1290, 1515), Vector2(1355, 1515), Vector2(1420, 1515)],
}
for uid in place:
	var k = 0
	for m in st.units[uid].models:
		m.position = {"x": place[uid][k].x, "y": place[uid][k].y}
		k += 1
	if st.units[uid].has("flags"):
		st.units[uid].flags.erase("last_shot_idx")
		st.units[uid].flags.erase("shot_recently")
for uid in st.units:
	if place.has(uid):
		continue
	var u = st.units[uid]
	var q = 0
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		if int(u.get("owner", 0)) == 1:
			m.position = {"x": 600.0 + 40.0 * float(q % 5), "y": 300.0}
		else:
			m.position = {"x": 1500.0 + 40.0 * float(q % 5), "y": 2300.0}
		q += 1
# Engine premises: Beta cannot see Alpha (Hidden, 13.09), the Prosecutors can.
return not RulesEngine.unit_sight_line("U_CUSTODIAN_GUARD_B", "U_CUSTODIAN_GUARD_A_P2", st, false).has_los and RulesEngine.unit_sight_line("U_PROSECUTORS_A", "U_CUSTODIAN_GUARD_A_P2", st, false).has_los

# FIX_INDIRECT_STATIONARY ships OFF: load the opt-in profile AFTER configure()
# (configure wipes profiles).
var f = FileAccess.open("res://tests/bench_profiles/indirect_stationary_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return prof.parameters.size()

# Engine-level check of the same suggestion: Custodian Guard Beta, a
# REMAIN_STATIONARY that says it arms its indirect fire, with the hold key.
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
return str(d.get("type", "")) == "REMAIN_STATIONARY" and str(d.get("actor_unit_id", "")) == "U_CUSTODIAN_GUARD_B" and str(d.get("_ai_description", "")).begins_with("Custodian Guard Beta remains stationary to arm its indirect fire at Custodian Guard Alpha") and bool(d.get("_ai_indirect_hold", false))

# SHIPPED-DEFAULT CHECK: clearing the profile leaves FIX_INDIRECT_STATIONARY
# at 0 — the planned Normal move, the old description, no hold key.
AIDecisionMaker.clear_player_profile(1)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
return str(d.get("type", "")) == "BEGIN_NORMAL_MOVE" and str(d.get("_ai_description", "")).begins_with("Custodian Guard Beta moves toward obj") and not d.has("_ai_indirect_hold") and not str(d.get("_ai_description", "")).contains("indirect")

# ...and reloading the profile restores the stay.
var f = FileAccess.open("res://tests/bench_profiles/indirect_stationary_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
return str(d.get("type", "")) == "REMAIN_STATIONARY" and str(d.get("_ai_description", "")).begins_with("Custodian Guard Beta remains stationary to arm its indirect fire at Custodian Guard Alpha")

# Execute the stay as the AI would (AIPlayer routes the decision as-is), then
# ask the ENGINE: Remained Stationary (09.04), every model where it stood, and
# armed — its hits at Alpha fail only on 1-3 (10.07).
var place = {
	"U_CUSTODIAN_GUARD_B": [Vector2(60, 870), Vector2(125, 870), Vector2(190, 870), Vector2(92, 935), Vector2(157, 935)],
	"U_CUSTODIAN_GUARD_D": [Vector2(60, 720), Vector2(125, 720), Vector2(190, 720), Vector2(92, 785), Vector2(157, 785)],
	"U_PROSECUTORS_A": [Vector2(790, 1340), Vector2(845, 1340), Vector2(790, 1395), Vector2(845, 1395)],
	"U_CUSTODIAN_GUARD_A_P2": [Vector2(1255, 1385), Vector2(1255, 1450), Vector2(1290, 1515), Vector2(1355, 1515), Vector2(1420, 1515)],
}
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var r = NetworkIntegration.route_action({"type": "REMAIN_STATIONARY", "actor_unit_id": "U_CUSTODIAN_GUARD_B", "player": 1, "_ai_description": str(d.get("_ai_description", ""))})
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var still = true
var k = 0
for m in u.models:
	var p = m.get("position")
	var pv = p if p is Vector2 else Vector2(float(p.x), float(p.y))
	if pv.distance_to(place.U_CUSTODIAN_GUARD_B[k]) > 1.0:
		still = false
	k += 1
return r != null and bool(r.get("success", false)) and bool(u.get("flags", {}).get("remained_stationary", false)) and still and RulesEngine._indirect_hit_fail_band_11e("U_CUSTODIAN_GUARD_B", "U_CUSTODIAN_GUARD_A_P2", GameState.state) == 3

# The guard: Delta, same spotter and target but a BS 5+ lobba (6+ after the
# indirect cover either way, 02.02.01), still makes its planned Normal move.
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_D")
return str(d.get("type", "")) == "BEGIN_NORMAL_MOVE" and str(d.get("actor_unit_id", "")) == "U_CUSTODIAN_GUARD_D" and not str(d.get("_ai_description", "")).contains("to arm its indirect fire") and not d.has("_ai_indirect_hold")
